#!/usr/bin/env python3
"""Make results/INDEX.md and registry/COVERAGE.md from REGISTRY.json. Do not edit those two files by hand. 25 Oct 2026.
Usage: python3 make_index.py"""
import collections, json, re
from pathlib import Path
HERE = Path(__file__).resolve().parent
WORK = HERE.parent
R = json.load(open(HERE / "REGISTRY.json"))
B = json.load(open(HERE / "backfill_report.json"))
C = json.load(open(HERE / "coverage_files.json"))
ST = list(R["status_values"])
E = R["entries"]
mods = R["modules"]


def cell(s):
    return (s or "").replace("|", "/").replace("\n", " ")[:160]


lines = ["# Results index", "",
         "Generated by `registry/make_index.py` from `registry/REGISTRY.json`. Do not edit this file by hand.",
         f"Registry built {R['built_utc']}; working-branch head at build: `{R['work_branch_head_at_build'][:12]}`.", "",
         "Use the registry id when you quote a number. A status is from existing records only (no new audit). "
         "UNCHECKED means: not yet used in a result that we quote. Check an item when you use it.", "",
         "Hydroacoustics results are not in this index. See `results/hydroacoustics/INDEX.md` and the hydroacoustics registry "
         "on branch `hypothesis/hydroacoustics` (phase 2 merges it).", ""]
for m in mods:
    rs = sorted((e for e in E if e["module"] == m and e["path"].startswith("WORK:results/")), key=lambda e: e["path"])
    if not rs:
        continue
    cnt = collections.Counter(e["status"] for e in rs)
    lines += [f"## {m} ({len(rs)} items)", "", "Status: " + ", ".join(f"{s} {cnt[s]}" for s in ST if cnt[s]), "",
              "| registry id | path under results/ | status | superseded by | description |", "|---|---|---|---|---|"]
    for e in rs:
        lines.append(f"| `{e['id']}` | {cell(e['path'][len('WORK:results/'):])} | {e['status']} | {('`' + e['superseded_by'] + '`') if e.get('superseded_by') else ''} | {cell(e.get('note'))} |")
    lines.append("")
(WORK / "results" / "INDEX.md").write_text("\n".join(lines) + "\n")

# coverage report
cv = ["# Registry coverage report", "", "Generated by `registry/make_index.py`. Do not edit this file by hand.", f"Registry built {R['built_utc']}.", "",
      "## Entries for each module and status", "", "| module | " + " | ".join(ST) + " | total |", "|---|" + "---|" * (len(ST) + 1)]
tot = collections.Counter()
for m in mods:
    c = collections.Counter(e["status"] for e in E if e["module"] == m); tot.update(c)
    cv.append(f"| {m} | " + " | ".join(str(c[s]) for s in ST) + f" | {sum(c.values())} |")
cv.append("| all | " + " | ".join(str(tot[s]) for s in ST) + f" | {sum(tot.values())} |")
cv += ["", "## Entries for each kind", "", "| kind | entries |", "|---|---|"]
for k, n in sorted(collections.Counter(e["kind"] for e in E).items()):
    cv.append(f"| {k} | {n} |")
rank = collections.Counter(e["status_rank"] for e in E)
cv += ["", "## Source of each status", "", "| source | entries |", "|---|---|"] + [f"| {k} | {v} |" for k, v in sorted(rank.items())]
ri = B["results_items"]
cv += ["", "## results/ coverage", "",
       f"- Folders under results/: {ri['folders_total']}. Loose files at the top of results/: {ri['loose_total']}.",
       f"- Registered here: {ri['registered_results_items']} items. Left for phase 2 (hydroacoustics): {ri['hydro_items']} items.",
       f"- Tracked files on the branch: {C['tracked']}. Files in a manifest of this registry: {C['covered']}.", ""]
ex = [e for e in E if e["path"].startswith("EX:") and e.get("manifest")]
nh = sum(len(e.get("not_hashed", [])) for e in ex)
cv += ["## Exchange folder", "", f"- Entries: {len(ex)}. Files: {sum(e['n_files'] for e in ex)}. Bytes: {sum(e['bytes'] for e in ex)}.",
       f"- Files with no SHA-256 (1 GB or more and no SHA256SUMS entry): {nh}. List: " + ", ".join(f"`{x}`" for e in ex for x in e.get("not_hashed", [])), "",
       "- The hydroacoustics part of the exchange folder is not in this registry (phase 2).",
       "- Memory records say that `end-of-flight/run-i` and `end-of-flight/run-i-c2aim` are superseded by `run-i-dive`. These folders are not in the exchange folder now, so they have no entry.", ""]
cv += ["## Files that are not registered, and why", "", "| file | reason |", "|---|---|"]
for p in C["not_covered"]:
    why = "hydroacoustics: left for phase 2" if re.search(r"(?i)hydro", p) and not p.startswith("Claude Science Project Sep 29/registry/") else ("registry's own file (scripts, manifests, generated outputs); a registry does not list itself" if p.startswith("Claude Science Project Sep 29/registry/") else ("archive folder manifest note (described by project.note.archive-sep29-manifest)" if p.startswith("Archive Sep 29") else "not matched by an entry rule"))
    cv.append(f"| {cell(p)} | {why} |")
cv += ["", "## Status statements found but not applied", "",
       "These records name an item and a status word, but the statement is about another item. They are listed for review.", "",
       "| entry | source | statement |", "|---|---|---|"] + [f"| `{a}` | {b} | {cell(c)} |" for a, b, c in B.get("statements_not_applied", [])]
cv += ["", "## Name chains with a later date, not applied", "",
       "A later date can be a continuation, not a replacement. These keep their own status.", ""] + [f"- {', '.join('`' + x + '`' for x in g)}" for g in B.get("date_chains_not_applied", [])]
cv += ["", "## Not registered in this phase (hydroacoustics)", ""] + [f"- {k}: {len(B.get(k, []))}" for k in
       ("results_hydro_left_for_phase2", "coordination_hydro_left_for_phase2", "threads_hydro_left_for_phase2", "xdrive_hydro_left_for_phase2")]
(HERE / "COVERAGE.md").write_text("\n".join(cv) + "\n")
print("INDEX.md and COVERAGE.md written;", sum(tot.values()), "entries")
